import base64

def decode_site_hash(encoded_string):
    """Decodes a Base64 string, adding padding if necessary."""
    try:
        # Base64 requires the string length to be a multiple of 4.
        # This adds '=' padding to the end if it's missing.
        padded_string = encoded_string + '=' * (-len(encoded_string) % 4)
        
        # Decode the string
        decoded_bytes = base64.b64decode(padded_string)
        decoded_text = decoded_bytes.decode('utf-8')
        
        return decoded_text
    except Exception as e:
        return f"Decoding failed: {e}"

# The CloudStream Pro hash from your HTML snippet
cloudstream_hash = ""

print("Decoded CloudStream Pro Hash:")
print(decode_site_hash(cloudstream_hash))